class NativeFlashCommitOwner final {
 using G=NativeGlobalReceive;using C=NativeFlashCommit;using N=NativeFlashReadonlyNotice;using B=NativeFlashBankStore;using Job=std::variant<std::monostate,G,C,N,B>;
public:enum class External:uint8_t {None,Program,Display,Load,Index};struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,3>CodeRanges{{{0x4d3a,0x4d96},{0x4dc0,0x4df0},{0x4e06,0x4e4c}}};static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}void reset(){for(auto&j:jobs_)j.emplace<std::monostate>();depth_=0;}bool active()const{return depth_!=0;}
 // The caller verifies the return address before admission.
 bool admit(Stage1Cpu&c,uint32_t verifiedReturn){if(depth_||midi_projection::blocked(c))return false;auto pc=uint32_t(c.getPC());if(pc==0x4e3c)jobs_[depth_++].emplace<G>(verifiedReturn);else if(pc==0x4dc0)jobs_[depth_++].emplace<C>(verifiedReturn);else if(pc==0x4e06)jobs_[depth_++].emplace<N>(verifiedReturn);else if(pc==0x4d3a||pc==0x4e10)jobs_[depth_++].emplace<B>(pc==0x4d3a?FlashBankStoreTask::Kind::Patch:FlashBankStoreTask::Kind::Performance,uint32_t(c.reg32(1)),verifiedReturn);else return false;return true;}
 External external()const{if(!depth_)return External::None;if(auto*p=std::get_if<G>(&jobs_[depth_-1]);p&&p->task().awaitingChild()&&p->task().child()==GlobalReceiveTask::Child::Load)return External::Load;if(auto*p=std::get_if<C>(&jobs_[depth_-1]);p&&p->task().awaitingChild()&&p->task().child()==FlashCommitTask::Child::Program)return External::Program;if(auto*p=std::get_if<N>(&jobs_[depth_-1]);p&&p->task().awaitingChild())return External::Display;if(auto*p=std::get_if<B>(&jobs_[depth_-1]);p&&p->task().awaitingChild()&&p->task().child()==FlashBankStoreTask::Child::Index)return External::Index;return External::None;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;for(unsigned n=0;n<jobs_.size()+1;++n){if(!depth_)return false;auto&j=jobs_[depth_-1];if(awaiting(j)){if(resume(j,c)){if(complete(j)){j.emplace<std::monostate>();--depth_;}continue;}if(depth_==jobs_.size())return false;if(auto*p=std::get_if<B>(&j);p&&p->task().child()==FlashBankStoreTask::Child::Commit&&uint32_t(c.getPC())==0x4dc0){jobs_[depth_++].emplace<C>(p->callerReturn());continue;}if(auto*p=std::get_if<G>(&j);p&&p->task().child()==GlobalReceiveTask::Child::Commit&&uint32_t(c.getPC())==0x4dc0){jobs_[depth_++].emplace<C>(0x4e48);continue;}if(auto*p=std::get_if<C>(&j);p&&p->task().child()==FlashCommitTask::Child::Notice&&uint32_t(c.getPC())==0x4e06){jobs_[depth_++].emplace<N>(0x4de6);continue;}return false;}bool ok=std::visit([&](auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.step(c);},j);if(!ok)return false;if(complete(j)){j.emplace<std::monostate>();--depth_;}return true;}return false;}
private:static bool awaiting(const Job&j){return std::visit([](const auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.task().awaitingChild();},j);}static bool complete(const Job&j){return std::visit([](const auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return true;else return v.task().complete();},j);}static bool resume(Job&j,Stage1Cpu&c){return std::visit([&](auto&v)->bool{using V=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<V,std::monostate>)return false;else return v.resumeChild(c);},j);}std::array<Job,3>jobs_{};unsigned depth_=0;
};
